462: \begin{lem}\label{lem:NC-quotient}
463: Let $M > 0, \tau > 0$ and consider a set $W$ such that for every $\mathbf{a} \in W$, we have
464: \[M^{-1}\tau \leq \abs{I_\mathbf{a}} \leq M\tau.\]
465: There is a constant $C = C(\Gamma, M) > 0$ such that for every $y \in \R$ and $\sigma \geq \tau$, we have
466: \[\#\left\{\mathbf{a} \in W\,:\,\abs{\frac{c_\mathbf{a}}{d_\mathbf{a}} - y} \leq \sigma\right\} \leq C\tau^{-\delta}\sigma^{\delta}.\]
467: \end{lem}

1582: \begin{lemma}\label{LE:free_HS_est_exponential_mixing}
1583: Let $X=\Gamma\setminus \bH$, where $\Gamma$ be a strictly hyperbolic Fuchsian group, and let $\tau\in\R$. Let $P_0(t)$ and $\widetilde{P}_0(t,\tau)$ be the free and modified free wave propagator associated with $-\Delta_X$. Moreover, suppose that $a\in L^\infty(X)$ with zero average and that there exist $C_1>0$ and $\kappa>1$ such that  
1584: \begin{equation}\label{LEEQ:free_HS_est_exponential_mixing_1}
1585:   \big|\langle a \circ \phi_r, a \rangle \big| \leq C_1 (t+1)^{-\kappa} \lVert a \rVert_{L^2(X)}^2,\quad r \geq 0.  
1586: \end{equation}
1587: %
1588: Then for all $T\geq 1$, we have the estimates
1589: %
1590: \begin{equation*}
1591:        \Big\lVert \int_0^T  P_0(t) a \boldsymbol{1}_{X( > 2T)} P_0(t) \,d t  \Big\rVert_{\bHS}^2 \leq g_\kappa(T) \norm{a}^2_{L^2(X)}+  4\pi T^3 \norm{a}_{L^\infty(X)}^2 \vol(X(\leq 2T)),
1592: \end{equation*}
1593: and 
1594: \begin{equation*}
1595:        \Big\lVert \int_0^T  \widetilde{P}_0(t,\tau) a \boldsymbol{1}_{X( > 2T)} P_0(t) \,d t  \Big\rVert_{\bHS}^2 \leq g_\kappa(T) \norm{a}^2_{L^2(X)}+  4\pi T^3 \norm{a}_{L^\infty(X)}^2 \vol(X(\leq 2T)),
1596: \end{equation*}
1597: where 
1598: \begin{equation*}
1599:     g_\kappa(T) = \begin{cases}
1600:         \frac{\kappa C_1}{\kappa -1} T^{3-\kappa} & \text{if $1<\kappa<2$,}\\
1601:         2 C_1(T+1)\ln (T+1) & \text{if $\kappa\geq 2$.}
1602:     \end{cases}        
1603: \end{equation*}
1604: \end{lemma}

